"""Hidden behavioral tests for cmark: render_commonmark. Generated by pbkit from the gold binary."""


def test_kitchen_sink_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'# Heading *one*\n\nSetext heading\n--------------\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard\\\nbreak and a soft\nbreak. Entities: &copy; &#x27; &#39; &nbsp;. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n>\n> > nested quote\n\n1. first\n2. second\n   - nested bullet\n   - another\n\n     with a paragraph\n3. third\n\n- [ ] not a task list\n* different bullet\n\n```python\ndef f(x):\n    return x * 2\n```\n\n    indented code block\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n***\n\n[ref link][ref] and [collapsed][] and [shortcut].\n\n[ref]: /url "ref title"\n[collapsed]: </with spaces>\n[shortcut]: http://x.y \'single\'\n')
    assert r.stdout == b'# Heading *one*\n\n## Setext heading\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard  \nbreak and a soft\nbreak. Entities: \xc2\xa9 \' \' \xc2\xa0. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n> \n> > nested quote\n\n1.  first\n2.  second\n      - nested bullet\n    \n      - another\n        \n        with a paragraph\n3.  third\n\n<!-- end list -->\n\n  - \\[ \\] not a task list\n\n<!-- end list -->\n\n  - different bullet\n\n``` python\ndef f(x):\n    return x * 2\n```\n\n``` \nindented code block\n```\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n-----\n\n[ref link](/url "ref title") and [collapsed](/with%20spaces) and [shortcut](http://x.y "single").\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_lists_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'- a\n- b\n\n- c\n\n1) x\n2) y\n\n10. ten\n11. eleven\n\n* loose\n\n  para\n* tight\n')
    assert r.stdout == b'  - a\n\n  - b\n\n  - c\n\n<!-- end list -->\n\n1)  x\n2)  y\n\n<!-- end list -->\n\n10. ten\n11. eleven\n\n<!-- end list -->\n\n  - loose\n    \n    para\n\n  - tight\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_special_chars_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'Special: \\ { } $ & # ^ _ % ~ < > " \' | and . at line start\n\n.SH not a macro\n\'quote\n')
    assert r.stdout == b'Special: \\\\ { } $ & \\# ^ \\_ % ~ \\< \\> " \' | and . at line start\n\n.SH not a macro\n\'quote\n'
    assert r.stderr == b''
    assert r.returncode == 0


