def test_links_and_urls_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'[a](<b c>) [d](e(f)g) [h](i\\)j) [k](l "m" ) [n](javascript:alert(1)) [o](data:image/png;base64,x) [p](vbscript:x) [q](file:///etc) ![r](data:text/html;x) <javascript:y>\n')
    assert r.stdout == b'[a](b%20c) [d](e\\(f\\)g) [h](i\\)j) [k](l "m") [n](javascript:alert\\(1\\)) [o](data:image/png;base64,x) [p](vbscript:x) [q](file:///etc) ![r](data:text/html;x) <javascript:y>\n'
    assert r.stderr == b''
    assert r.returncode == 0


