def test_code_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'``` js {.class}\nconsole.log(`x`);\n```\n\n``` \n~~~\n```\n\n``a`b``\n\n```` \n```\n````\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_breaks_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'line one\nline two  \nline three  \nline four\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'> 1.  >   - a\n>     >     b\n> \n> 2.  c\n>     \n>     ``` \n>     code in list\n>     ```\n'
    assert r.stderr == b''
    assert r.returncode == 0
